"""Compose new source-reviewed sequences; do not modify earlier research."""
import copy
import hashlib
import json
from pathlib import Path
from datetime import datetime, timezone

HERE = Path(__file__).resolve().parent
PREVIOUS = HERE.parent / 'workshop-2026'
SOURCE = PREVIOUS / 'valve-inspection-v1.procedure.json'
BASE = json.loads(SOURCE.read_text(encoding='utf-8-sig'))
URL = BASE['source']['source_url']
STAMP = datetime.now(timezone.utc).isoformat()

def save(name, obj):
    (HERE / name).write_text(json.dumps(obj, indent=2) + '\n', encoding='utf-8')

def step(id, title, instruction, pages, verification, diagram=True):
    return {'id':id,'title':title,'instruction':instruction,'depends_on':[],
            'source_pdf_pages':pages,'verification':[verification],
            'diagram_reference_required':diagram,
            'source_links':[URL+'#page='+str(n) for n in pages] if diagram else [],
            'origin':'Original source-based summary; logging and fault-stop actions are workflow adaptations.'}

def prepare(id, title, scope):
    p = copy.deepcopy(BASE)
    p.update(id=id,title=title,completeness=scope,reviewed_at=STAMP)
    p['source']['pdf_pages'] = sorted(set(p['source']['pdf_pages']+[58,93,94,95,217,218,219,220]))
    p['source']['printed_pages'] += ['2-11','3-9 to 3-11','5-14 to 5-17']
    p['source']['review_note'] = 'Existing reviewed assembled-bike valve access/closure retained. Additional PDF92-95 and216-221 visually reviewed for shim selection, cam/tensioner removal, installation and timing recheck. Exact diagrams remain mandatory where flagged.'
    p['derivation']={'source_artifact':'../workshop-2026/valve-inspection-v1.procedure.json','sha256':hashlib.sha256(SOURCE.read_bytes()).hexdigest(),'method':'Reuses reviewed access and closure only; newly reviewed internal steps inserted. Original file unchanged.'}
    p['required_tools'] += [{'name':'Thin screwdriver','purpose':'Wind the stock automatic tensioner inward clockwise while lightly pressing its rod'}, {'name':'Clean wire and labeled parts storage','purpose':'Retain timing chain and original cam/cap positions'}]
    p['required_parts'] += [{'name':'New tensioner gaskets at positions 1, 3 and 5','purpose':'Body gasket, illustrated mounting-bolt gasket and cap-bolt gasket; preserve positions in PDF220-221 diagrams','source_pdf_page':220}]
    p['critical_stop_conditions'] = ['Abnormal hand-rotation resistance, ambiguous timing marks, lost chain engagement or loose material in engine.', 'Tensioner fails to extend smoothly or is cracked/damaged.', 'Any final cold clearance outside its range or unresolved measurement.', 'Dirt enters engine/fuel circuit, sealing location unknown or fuel connector does not latch.']
    p['applicability']['excluded'] = ['Other model years','YZ450FX','Aftermarket camshafts, valve train or manual tensioner','Cylinder/head/piston removal','Complete engine rebuild']
    p['exclusions_detail'] = ['No oil-nozzle removal, cylinder-head removal, piston/ring work, valve-seat repair or cam journal repair.','Source-diagram dependencies must be visible during work, not reduced to an unlabelled text checklist.','Not physically tested on a motorcycle; completion requires recorded checks and does not establish general ride readiness.']
    p['preflight'] += ['New tensioner sealing gaskets and a suitable thin screwdriver available; identify the exact stock tensioner and diagram positions before opening.']
    p['steps'] = copy.deepcopy(BASE['steps'][:10])
    p['steps'][0]['instruction'] = p['steps'][0]['instruction'].replace('during this inspection','during this operation')
    s = next(s for s in p['steps'] if s['id']=='cover-remove')
    s['instruction'] = s['instruction'].replace(' Do not remove cam caps, camshafts, tensioner or shims for this inspection.', ' Retain the top chain guide and do not remove any cam or tensioner hardware until the TDC and measurement steps are completed.')
    return p

REMOVE_TENSIONER = step('tensioner-remove','Remove the unloaded tensioner assembly','Keep the engine at the confirmed TDC position. Remove the tensioner cap bolt and its gasket, then remove the mounting bolts and tensioner with its body and mounting-bolt gaskets. Preserve the sealing locations shown. Do not rotate the crankshaft with the tensioner removed.',[216,217],'Tensioner removed; crank position unchanged; gasket locations retained.')
CHECK_TENSIONER = step('tensioner-check','Check tensioner action','Inspect the tensioner for cracks or damage. While lightly pressing the rod with a finger, turn its screw fully clockwise with a thin screwdriver to retract it. Release the screwdriver while maintaining light finger pressure and verify that the rod extends smoothly. Replace a damaged or sticking unit; do not install one that fails this check.',[219],'No cracks/damage; rod retracts and extends smoothly.')
INSTALL_TENSIONER = step('tensioner-install','Install the retracted tensioner','Lightly press the rod and wind it fully clockwise again. Keep it fully retracted while installing the tensioner with its UP mark facing upward, a new body gasket at position 1 and the new mounting-bolt gasket at position 3 in the source diagram. Tighten the mounting bolts to 10 N·m. Do not release the screwdriver until the assembly is secured.',[220],'UP mark upward; new gaskets correctly located; mounting bolts 10 N·m; rod held retracted until secured.')
RELEASE_TENSIONER = step('tensioner-release','Release the tensioner','Release the screwdriver and verify smooth rod extension. Fit the new cap-bolt gasket at position 5 and tighten the cap bolt to 6 N·m. Account for the screwdriver before rotating the engine.',[220,221],'Rod released and extended; new cap gasket fitted; cap bolt 6 N·m.')
TIMING = step('timing-verify','Verify timing by hand','With cam caps and tensioner fully installed, turn the crankshaft counterclockwise by hand for several complete turns. Stop at abnormal resistance. Return to the rotor TDC mark and confirm both cam-sprocket match marks align with their specified head/cap surfaces as illustrated. If any mark is wrong, do not start the engine; correct timing through the cam installation sequence before repeating this check.',[217,220,221],'Smooth hand rotation; rotor TDC and both cam marks align after several turns.')
REMEASURE = step('remeasure','Measure all four clearances again','At the verified TDC position and with the engine still at room temperature, measure between each cam lobe and its lifter. Record all four results. Each intake must be 0.10–0.17 mm; each exhaust must be 0.15–0.22 mm. An unresolved boundary or out-of-range result is not a completed adjustment.',[91,92,93],'Four definite cold readings recorded; all within exact ranges.',True)

def finish(p):
    close = copy.deepcopy(BASE['steps'][11:])
    close[-1]['instruction'] = 'Restore fuel safely and secure the tank cap. Account for tools, wire, cloths, joint covers and hardware. Check for trapped hoses/wires/seals and any fuel leak. Save before/after readings, timing verification, replaced parts and actual work performed. Mark only this bounded operation complete when all final measurements and assembly checks pass; record unresolved faults instead of claiming repair.'
    p['steps'] += close
    for i,s in enumerate(p['steps']):
        s['depends_on']=[] if i==0 else [p['steps'][i-1]['id']]
        s['record_required']=s['id'] in ['tdc','measure','assess','adjustment-scope','service-scope','tensioner-check','pads-remove','pads-select','caps-install','tensioner-install','tensioner-release','timing-verify','remeasure','closeout']
    p['source']['pdf_pages']=sorted(set(p['source']['pdf_pages']+[n for s in p['steps'] for n in s['source_pdf_pages']]))
    return p

p = prepare('yamaha-2026-yz450f-valve-adjustment-v2','Adjust cold valve clearances','Complete assembled-bike access, four-valve measurement, cam removal, OEM chart-based pad selection, cam/tensioner installation, timing verification, remeasurement and closure for supported chart inputs. No top-end rebuild claim.')
p['required_tools'] += [{'name':'Valve lapper, diameter 14 mm','part_numbers':['90890-04101','YM-A8998'],'purpose':'Lift each valve lifter and pad without mixing positions'}, {'name':'Exact OEM intake/exhaust shim charts','purpose':'PDF94 for intake, PDF95 for exhaust; readable chart required, no formula substituted'}]
p['required_parts'] += [{'name':'Correct stock adjusting pads selected from exact chart','purpose':'Available source range 1.20–2.40 mm in 0.05 mm increments; selected after original pads and cold measurements are known','source_pdf_page':92}, {'name':'Molybdenum disulfide oil','purpose':'Camshaft lubrication and valve-stem ends as shown; do not substitute molybdenum grease by name alone','source_pdf_page':219}]
p['preflight'] += ['Operator can read the exact intake/exhaust chart; this version provides a source-linked manual lookup rather than an automatic shim calculator.']
p['critical_stop_conditions'] += ['Original pad number unreadable or ends in 3 or 7; OEM rounding table omits those digits.', 'Measurement falls between displayed chart intervals, or chosen chart intersection is blank/outside the table; do not round or extrapolate.', 'Damaged cams, chain or sprockets require separate repair rather than a shim-only cure.']
p['steps'] += [step('adjustment-scope','Confirm adjustment is required','Compare the recorded readings with the intake and exhaust ranges. Continue into cam removal only for a definite out-of-range reading with otherwise serviceable stock valve-train components. If all four already meet specification, use the inspection procedure closure without changing pads. Uncertain measurements must be resolved before selecting a pad.',[91,92,93],'At least one definite out-of-range reading; four valve positions recorded.',False), copy.deepcopy(REMOVE_TENSIONER),step('cams-remove','Remove the cams without mixing positions','Loosen the cam-cap bolts evenly in a crisscross pattern from outside inward. Lift the caps and retain their dowels and exact original positions. Attach a clean wire to the chain to prevent it falling into the crankcase, then lift out the exhaust and intake cams. Leave the oil nozzle installed and retain crankshaft position.',[216,217],'Caps/dowels/cams identified; chain secured; crank unchanged; oil nozzle undisturbed.'),step('cams-condition','Check the retained components','Inspect cam lobes for blue discoloration, pitting or scratching; check the chain for damage or stiffness and sprockets for more than one-quarter tooth wear using the source diagram. Verify smooth decompressor-cam movement and projection of its lever pin. A failed check needs the specified separate component repair, not merely another pad.',[218,219],'No visible cam/chain/sprocket/decompressor fault; dimensional overhaul inspection not claimed.'),copy.deepcopy(CHECK_TENSIONER),step('pads-remove','Identify each original pad','Place a clean cloth in the timing-chain space while keeping the chain secured. Use the 14 mm valve lapper to lift the lifter and pad for each affected valve. Keep every lifter and original pad labeled by valve position. Read and record the original pad number before choosing a replacement.',[92],'Original number and exact position logged; cloth prevents dropped pads.'),step('pads-select','Select from the exact valve chart','For the original pad number, convert only the last digit as Yamaha lists: 0/1/2 to 0, 4/5/6 to 5, and 8/9 to the next ten. For example, 148 becomes 150. Digits 3 and 7 are unspecified and stop selection. Use the intake chart on PDF94 or exhaust chart on PDF95: intersect the converted original pad column with the row containing the measured cold clearance. Record the selected number. A blank cell, unreadable number or reading outside/between listed intervals is unresolved; never extrapolate. The new pad must be the correct stock part with that chart number.',[92,94,95],'Each selected pad traced to recorded valve, measured row and original-pad column; no unsupported digit or blank cell.'),step('pads-install','Install the selected pads and original lifters','Apply molybdenum disulfide oil to the valve-stem ends and engine oil to the lifters. Install the selected pads with their numbers facing upward and return each original lifter to its own position. Seat them without forced twisting and verify each lifter turns smoothly by finger. Account for and remove the protective cloth before cam installation while keeping the chain secured.',[92,93],'Pads number-side up; lifters in original positions and move smoothly; cloth removed.'),step('cams-install','Set the cams at the exact timing marks','Confirm the retained rotor TDC alignment. Apply molybdenum disulfide oil to the camshaft locations shown and engine oil to the decompression system. Fit the chain onto both stock sprockets and seat the exhaust and intake cams with both match marks at the illustrated cap-surface edges. Do not turn the crankshaft during cam installation. Remove the retaining wire only after the chain is supported correctly on the sprockets.',[219,220],'TDC unchanged; both cam marks aligned; chain seated; retaining wire removed.'),step('caps-install','Tighten the cam caps evenly','Restore the dowels and original cam caps. Apply engine oil to bolt threads and contact faces. Tighten all eight cap bolts evenly in two or three stages to 10 N·m, following numbered positions 1 through 8 in the PDF220 diagram. Keep the numbered diagram visible; do not invent a left/right order from memory.',[216,218,220],'Original caps/dowels fitted; all eight bolts 10 N·m in source numbered sequence with oiled threads/contact faces.'),copy.deepcopy(INSTALL_TENSIONER),copy.deepcopy(RELEASE_TENSIONER),copy.deepcopy(TIMING),copy.deepcopy(REMEASURE)]
p['repeat_policy']={'trigger':'Any remeasured clearance is outside specification','action':'Repeat cam removal, chart selection, pad installation, cam/tensioner assembly and all timing/clearance checks with the newly installed pad recorded as the original for that iteration. Never loosen caps against an installed tensioner or skip timing verification.','source_pdf_pages':[92,93,217,220,221],'success':'All four definite cold readings within range; full closure complete.'}
p['chart_policy']={'mode':'MANUAL_OEM_LOOKUP_ONLY','intake_pdf_page':94,'exhaust_pdf_page':95,'unsupported_original_pad_last_digits':[3,7],'blank_cell':'STOP_NO_SELECTION','between_chart_intervals':'STOP_RESOLVE_MEASUREMENT','automatic_formula':None}
save('valve-adjustment-v2.procedure.json',finish(p))

p = prepare('yamaha-2026-yz450f-stock-tensioner-service-v1','Check or replace the stock timing-chain tensioner','Complete assembled-bike access, TDC/clearance checks, stock automatic tensioner removal, functional check or replacement, new gasket installation, timing/clearance verification and closure. Camshafts and shims remain installed throughout.')
p['required_parts'] += [{'name':'Exact stock automatic timing-chain tensioner, when the original fails inspection','purpose':'Verify exact model applicability before installation; manual/aftermarket conversions excluded','source_pdf_page':219}]
p['applicability']['excluded'] += ['Camshaft/cap removal','Shim adjustment']
p['steps'] += [step('service-scope','Confirm the bounded service','Proceed only with clear timing marks and four in-range cold readings. Camshafts, caps, pads and lifters remain installed. This operation checks or replaces the stock tensioner; it cannot repair an already mistimed engine or resolve valve-clearance faults.',[91,217,219],'Initial timing and all four clearances pass; stock tensioner confirmed.',False),copy.deepcopy(REMOVE_TENSIONER),copy.deepcopy(CHECK_TENSIONER),copy.deepcopy(INSTALL_TENSIONER),copy.deepcopy(RELEASE_TENSIONER),copy.deepcopy(TIMING),copy.deepcopy(REMEASURE)]
next(s for s in p['steps'] if s['id']=='timing-verify')['instruction'] += ' Timing correction requires the separate reviewed cam operation; this tensioner-only sequence does not remove the cams.'
save('stock-tensioner-service-v1.procedure.json',finish(p))
print('Created two source-reviewed bounded procedures.')
